// Shared table for REQ-M4a (test/shell-normalise.smoke.mjs). Kept in its own
// module so the before/after report can run the same rows against any build of
// shellPolicy.ts without running the smoke's assertions.

// ─── Positive controls: each of these must get the strong confirm ────────────
// The first eight are the verifier's list, verbatim.
export const BYPASS_FORMS = [
  "\\rm -rf ~",
  "'rm' -rf ~",
  '"rm" -rf ~',
  "FOO=1 rm -rf ~",
  "env rm -rf ~",
  "command rm -rf ~",
  "git push '--force'",
  "git reset '--hard'",
  // quoting and escaping inside the command word
  "r''m -rf ~",
  'r""m -rf ~',
  "r\\m -rf ~",
  '"r"m -rf ~',
  "$'\\x72m' -rf ~",
  // assignments and env
  "A=1 B=2 rm -rf ~",
  "env FOO=1 rm -rf ~",
  "env -i PATH=/bin rm -rf ~",
  "env -S 'rm -rf ~'",
  "/usr/bin/env rm -rf ~",
  "GIT_DIR=.git git reset --hard",
  // absolute paths and case
  "/bin/rm -rf ~",
  "/bin/'rm' -rf ~",
  "RM -rf ~",
  "Rm -rf ~",
  "/BIN/RM -rf ~",
  // wrappers
  "time rm -rf ~",
  "time -p 'rm' -rf ~",
  "nice -n 10 'rm' -rf ~",
  "nohup 'rm' -rf ~ &",
  "exec 'rm' -rf ~",
  "timeout 5 'rm' -rf ~",
  "command -p 'rm' -rf ~",
  "busybox rm -rf ~",
  "watch -n 2 'rm -rf ~'",
  "stdbuf -o0 'rm' -rf ~",
  "rm${IFS}-rf ~",
  "r$()m -rf ~",
  "X=$(rm -rf ~)",
  "case a in a) 'rm' -rf ~;; esac",
  "sudo -u root ls",
  "'sudo' ls",
  // xargs and find
  "ls | xargs rm",
  "ls | xargs -0 'rm' -f",
  "ls | xargs -n 1 \\rm",
  "xargs -I{} sh -c 'rm {}'",
  "find . -delete",
  "find . -name '*.html' -delete",
  "find . -exec rm {} \\;",
  "find . -exec 'rm' -f {} +",
  "find . -execdir sh -c 'rm \"$0\"' {} \\;",
  // nested shells
  "bash -c 'rm -rf ~'",
  'sh -c "rm -rf ~"',
  "zsh -c 'git reset --hard'",
  "bash -lc 'rm -rf ~'",
  "bash -c \"FOO=1 'rm' -rf ~\"",
  "echo 'rm -rf ~' | bash",
  "bash <<'EOF'\nrm -rf ~\nEOF",
  "sh <<< 'rm -rf ~'",
  "eval 'rm -rf ~'",
  // substitution
  "echo $('rm' -rf ~)",
  "echo `\\rm -rf ~`",
  'echo "$(rm -rf ~)"',
  'echo "`rm -rf ~`"',
  "cat <(rm -rf ~)",
  "ls $(echo; 'rm' -rf ~)",
  // grouping, keywords and chains
  "git status && FOO=1 rm -rf ~",
  "if true; then 'rm' -rf ~; fi",
  "{ 'rm' -rf ~; }",
  "(cd /tmp && 'rm' -rf ~)",
  "true || \\rm -rf ~",
  "ls\n\\rm -rf ~",
  // rm long options (already caught by the verb; kept as a lock)
  "rm --recursive --force ~",
  "rm -r -f ~",
  "rm -fr ~",
  "rm -Rf ~",
  // git forms
  "git clean -fdx",
  "git clean '-fdx'",
  "git checkout -- .",
  "git checkout .",
  "git checkout '--' index.html",
  "git -C site push --force",
  "git -c core.x=y reset --hard",
  "git push origin +main",
  "git push --force-with-lease",
  "git push -uf origin main",
  "git branch '-D' feature",
  "git push origin :main",
  "git restore index.html",
  "git stash clear",
  "\\git push -f",
  // other verbs on the list, quoted
  "chmod -R 777 .",
  '"chmod" -R 777 .',
  "'dd' if=/dev/zero of=x",
  "mkfs.ext4 /dev/sdb1",
  "'shred' -u notes.txt",
  "\\truncate -s 0 index.html",
  // redirections that clobber
  "echo x > important.txt",
  "echo x >| index.html",
  "echo x &> index.html",
  "echo x > /tmp/../Users/me/index.html",
  // fail closed: what the tokeniser cannot read
  "$CMD -rf ~",
  "${CMD} -rf ~",
  "/bin/r? -rf ~",
  "/bin/r* -rf ~",
  "echo 'unterminated",
  'echo "unterminated',
  "echo `unterminated",
  "echo $(unterminated",
  "cat <<EOF\nno terminator",
  "cat <<EOF\n$(rm -rf ~)\nEOF",
];

